<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Theme\Domain\Event;

use Override;
use Civi\Lughauth\Features\Document\Theme\Domain\Theme;
use Civi\Lughauth\Shared\Event\PublicEvent;

class ThemeDeleteEvent extends ThemeEvent implements PublicEvent
{
    public function __construct(
        Theme $payload
    ) {
        parent::__construct($payload);
    }
    #[Override]
    public function eventType(): string
    {
        return 'theme.delete';
    }
    #[Override]
    public function schemaVersion(): string
    {
        return 'v1';
    }
    #[Override]
    public function payload(): array
    {
        return [];
    }
    #[Override]
    public function original(): array
    {
        return $this->payload->asPublicJson();
        ;
    }
}
